    const secondDelta = deltaActions[1].s.kind === "action" && deltaActions[1].s.action.type === ActionType.ChatDelta ? deltaActions[1].s.action : void 0;
    assert.ok(part, "ChatResponsePart action present");
    assert.ok(firstDelta, "first ChatDelta action present");
